// This file is not generated by Speakeasy — it bounds the stdin read that
// BuildRequest performs when a command accepts a request body.
//
// The problem it solves: `HasStdinInput` reports true for any non-TTY stdin,
// including a pipe that is open but will never carry data or close. io.ReadAll
// then blocks forever waiting for an EOF that never arrives, so the CLI hangs
// instead of failing. That affects every command with a body — 76 of 138 — and
// it is the worst possible failure for the audience this CLI targets, because a
// coding agent or CI job stalls with no output and nothing to act on.
//
// Two shapes hang, and both are covered here:
//
//	sleep 30 | vf agent update ...          # never writes, never closes
//	( echo '{}'; sleep 30 ) | vf ...        # writes, then holds the write end
//
// Deciding whether to read is done by file type, never by polling for
// readiness. A readiness check cannot distinguish "silent forever" from "slow by
// ten milliseconds" without waiting, and waiting is what it was meant to avoid:
// measured against real producers, a zero-timeout poll discarded the body from
// curl, node and python3 pipelines every single time, which is silent data loss
// dressed up as a fix. Reading with a deadline is slower in the pathological
// case and correct in every other one.

package flagutil

import (
	"errors"
	"fmt"
	"io"
	"time"
)

// StdinReadTimeout bounds how long a command will wait for piped input before
// giving up. Generous on purpose: a producer doing real work first — a network
// fetch, a large transform, another CLI — must comfortably fit inside it, since
// dropping that input silently would be worse than the hang this replaces.
const StdinReadTimeout = 10 * time.Second

// ErrStdinTimeout is returned when stdin stayed open past StdinReadTimeout
// without delivering data or closing.
var ErrStdinTimeout = errors.New("timed out reading stdin")

// readStdinBounded reads r to EOF, giving up after StdinReadTimeout.
//
// On timeout the read goroutine is abandoned while it is still parked in
// read(2). That leaks one goroutine and its OS thread for the remaining life of
// the process, which is acceptable here and nowhere else: this runs once per
// invocation of a short-lived CLI that is about to exit. The alternative —
// putting the file descriptor into non-blocking mode — mutates the open file
// description that the parent shell shares, so it would corrupt the caller's
// terminal on any exit path that failed to restore it.
func readStdinBounded(r io.Reader) ([]byte, error) {
	type result struct {
		data []byte
		err  error
	}
	done := make(chan result, 1) // buffered so the abandoned goroutine can finish and exit

	go func() {
		data, err := io.ReadAll(r)
		done <- result{data: data, err: err}
	}()

	timer := time.NewTimer(StdinReadTimeout)
	defer timer.Stop()

	select {
	case res := <-done:
		return res.data, res.err
	case <-timer.C:
		return nil, fmt.Errorf(
			"%w after %s: stdin is open but sent no data and never closed.\n"+
				"If you did not mean to pipe a request body, redirect it: vf <command> </dev/null\n"+
				"If you did, make sure the producer closes its write end when it is finished",
			ErrStdinTimeout, StdinReadTimeout,
		)
	}
}
